//! A fake web server for the chat's `fetch_url` and `download_asset` tools (ai D27): a page, a
//! redirect chain, generated files of any size, a slow answer, and routes a test adds, such as a
//! PDF or an image. It answers HEAD with the headers alone and a `Range: bytes=0-0` GET with
//! the first byte and the total size, as real servers do.
//!
//! Built-in routes:
//!
//! | Route | Answer |
//! |---|---|
//! | `/page.html` | [`FAKE_PAGE`], `text/html` |
//! | `/redirect/<n>` | a 302 to `/redirect/<n-1>`, and `/redirect/0` a 302 to `/page.html` |
//! | `/to?url=<url>` | a 302 to `url` |
//! | `/bytes?size=<n>&type=<media type>` | `n` bytes of text lines (default type `text/plain`); `&nolength=1` sends no `Content-Length`, `&name=<file>` a `Content-Disposition` |
//! | `/slow?ms=<n>` | the page after `n` milliseconds |
//!
//! Any route with `nohead=1` in its query answers HEAD with 405, so a client falls back to a
//! ranged GET. A route a test added with [`FakeWeb::route`] wins over a built-in one.
//!
//! It binds `127.0.0.1` on a free port, or the loopback address [`FakeWeb::start_on`] names.

use std::collections::HashMap;
use std::io::Write;
use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use crate::standin::{Reply, Request, read_request, url_decode};

/// The HTML of `/page.html`: a title, page chrome the reader drops (a header, navigation, an
/// aside, a footer, scripts and a style), and the article it keeps, with a list and links.
pub const FAKE_PAGE: &str = r#"<!doctype html>
<html>
<head>
  <title>Slate roofs: a guide</title>
  <style>body { color: red }</style>
  <script>window.tracking = "SCRIPT-CONTENT";</script>
</head>
<body>
  <header><a href="/">Roofing Weekly</a> HEADER-CONTENT</header>
  <nav><ul><li><a href="/news">NAV-CONTENT</a></li></ul></nav>
  <main>
    <h1>Why slate lasts</h1>
    <p>Slate tiles last a hundred years. Read the <a href="/specs.html">full specs</a> or the
       <a href="https://example.org/history">history of slate</a>.</p>
    <ul>
      <li>Durable</li>
      <li>Fireproof</li>
    </ul>
  </main>
  <aside>ASIDE-CONTENT</aside>
  <footer>FOOTER-CONTENT</footer>
  <script>console.log("SCRIPT-CONTENT")</script>
</body>
</html>
"#;

#[derive(Default)]
struct Shared {
    routes: Mutex<HashMap<String, Reply>>,
    requests: Mutex<Vec<Request>>,
    stop: AtomicBool,
}

/// A running fake web server. Dropping it stops it.
pub struct FakeWeb {
    addr: SocketAddr,
    shared: Arc<Shared>,
}

impl FakeWeb {
    /// Start on `127.0.0.1` and a free port.
    pub fn start() -> FakeWeb {
        FakeWeb::start_on("127.0.0.1".parse().expect("loopback"))
    }

    /// Start on `ip`, such as another loopback address `127.0.0.2`, and a free port.
    pub fn start_on(ip: IpAddr) -> FakeWeb {
        let listener = TcpListener::bind(SocketAddr::new(ip, 0)).expect("bind the fake web server");
        let addr = listener.local_addr().expect("fake web address");
        let shared = Arc::new(Shared::default());
        let s = shared.clone();
        thread::spawn(move || {
            for conn in listener.incoming() {
                if s.stop.load(Ordering::SeqCst) {
                    return;
                }
                let Ok(conn) = conn else { continue };
                let s = s.clone();
                thread::spawn(move || {
                    let _ = serve(conn, &s);
                });
            }
        });
        FakeWeb { addr, shared }
    }

    /// Answer `path` (without its query) with `reply`.
    pub fn route(&self, path: &str, reply: Reply) {
        lock(&self.shared.routes).insert(path.to_owned(), reply);
    }

    pub fn addr(&self) -> SocketAddr {
        self.addr
    }

    /// `http://<addr><path>`.
    pub fn url(&self, path: &str) -> String {
        format!("http://{}{path}", self.addr)
    }

    /// Every request so far, in order.
    pub fn requests(&self) -> Vec<Request> {
        lock(&self.shared.requests).clone()
    }
}

impl Drop for FakeWeb {
    fn drop(&mut self) {
        self.shared.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(self.addr);
    }
}

fn lock<T>(m: &Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|e| e.into_inner())
}

/// What a route answers: a whole reply, or `size` generated bytes.
enum Body {
    Whole(Vec<u8>),
    Generated(u64),
}

struct Answer {
    status: u16,
    headers: Vec<(String, String)>,
    body: Body,
    /// Send `Content-Length`.
    length: bool,
    delay: Duration,
}

impl Answer {
    fn of(reply: Reply) -> Answer {
        Answer {
            status: reply.status,
            headers: reply.headers,
            body: Body::Whole(reply.body),
            length: true,
            delay: reply.delay,
        }
    }

    fn size(&self) -> u64 {
        match &self.body {
            Body::Whole(b) => b.len() as u64,
            Body::Generated(n) => *n,
        }
    }
}

fn redirect(to: &str) -> Answer {
    Answer::of(Reply::text(302, "moved").header("location", to))
}

fn page() -> Reply {
    let mut r = Reply::text(200, FAKE_PAGE);
    r.headers = vec![("content-type".into(), "text/html; charset=utf-8".into())];
    r
}

fn route(r: &Request, shared: &Shared) -> Answer {
    let path = r.route();
    if let Some(reply) = lock(&shared.routes).get(path).cloned() {
        return Answer::of(reply);
    }
    if path == "/page.html" {
        return Answer::of(page());
    }
    if let Some(n) = path.strip_prefix("/redirect/") {
        return match n.parse::<u32>() {
            Ok(0) => redirect("/page.html"),
            Ok(n) => redirect(&format!("/redirect/{}", n - 1)),
            Err(_) => Answer::of(Reply::text(404, "no route")),
        };
    }
    if path == "/to" {
        return redirect(&r.query("url").unwrap_or_default());
    }
    if path == "/bytes" {
        let size = r.query("size").and_then(|s| s.parse().ok()).unwrap_or(0);
        let media = r.query("type").unwrap_or_else(|| "text/plain".to_owned());
        let mut headers = vec![("content-type".to_owned(), media)];
        if let Some(name) = r.query("name") {
            headers.push((
                "content-disposition".to_owned(),
                format!("attachment; filename=\"{name}\""),
            ));
        }
        return Answer {
            status: 200,
            headers,
            body: Body::Generated(size),
            length: r.query("nolength").is_none(),
            delay: Duration::ZERO,
        };
    }
    if path == "/slow" {
        let ms = r.query("ms").and_then(|s| s.parse().ok()).unwrap_or(5_000);
        return Answer::of(page().delay(Duration::from_millis(ms)));
    }
    Answer::of(Reply::text(404, "no route"))
}

/// Byte `i` of a generated body: the same line of text over and over.
fn generated(i: u64) -> u8 {
    const LINE: &[u8] = b"The quick brown fox jumps over the lazy dog. 0123456789\n";
    LINE[(i % LINE.len() as u64) as usize]
}

fn serve(conn: TcpStream, shared: &Shared) -> std::io::Result<()> {
    let Some(request) = read_request(&conn)? else {
        return Ok(());
    };
    lock(&shared.requests).push(request.clone());
    let head_refused = request
        .path
        .split_once('?')
        .is_some_and(|(_, q)| q.split('&').any(|p| url_decode(p) == "nohead=1"));
    let mut answer = if request.method == "HEAD" && head_refused {
        Answer::of(Reply::text(405, "no HEAD"))
    } else {
        route(&request, shared)
    };
    thread::sleep(answer.delay);
    let total = answer.size();
    // A first-byte range, as a client asks when HEAD is refused.
    let ranged = answer.status == 200 && request.header("range") == Some("bytes=0-0") && total > 0;
    if ranged {
        answer.status = 206;
        answer
            .headers
            .push(("content-range".to_owned(), format!("bytes 0-0/{total}")));
    }
    let sent = if ranged { 1 } else { total };
    let mut out = conn;
    let mut head = format!("HTTP/1.1 {} Fake\r\nconnection: close\r\n", answer.status);
    if answer.length || ranged {
        head.push_str(&format!("content-length: {sent}\r\n"));
    }
    for (n, v) in &answer.headers {
        head.push_str(&format!("{n}: {v}\r\n"));
    }
    head.push_str("\r\n");
    out.write_all(head.as_bytes())?;
    if request.method == "HEAD" {
        return out.flush();
    }
    match &answer.body {
        Body::Whole(b) => out.write_all(&b[..sent as usize])?,
        Body::Generated(_) => {
            let mut i = 0u64;
            let mut buf = Vec::with_capacity(64 * 1024);
            while i < sent {
                buf.clear();
                while i < sent && buf.len() < 64 * 1024 {
                    buf.push(generated(i));
                    i += 1;
                }
                // The client may stop reading once it has enough.
                if out.write_all(&buf).is_err() {
                    return Ok(());
                }
            }
        }
    }
    out.flush()
}
